#!/bin/zsh
# Saison 2 : le héros se tourne vers son interlocuteur (demande de Stéphan, 24/11). La référence du héros change selon
# l'orientation voulue : hero_left.png (tourné vers la gauche), hero.png / hero_right.png (vers la droite), hero_front.png.
# Ajoute aussi Monkey Island avec l'apprenti pirate (Guybrush) et le capitaine fantôme (LeChuck).
# FLUX 3 Klein local, file calcul-lourd. Relançable : saute ce qui existe. Usage : gen_s2_orient.sh [id…]
cd "$(dirname "$0")/../work/crossover" || exit 1
mkdir -p persos
SP="full body game character sprite, hand-painted 2D point-and-click adventure game art of the early 2000s, sarcastic cartoon style with realistic proportions, detailed painterly shading, bold dark outlines, saturated warm colors, the whole figure visible with a margin around it, three-quarter view, plain flat solid magenta background, no shadow, no ground, no text"
ST="hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame, no text, no letters"
HL="The hero is exactly the man from the reference picture, same face, same blond ponytail, same horned iron Viking helmet, same fur-collared studded leather armor, same round wooden shield on his back, plus a brown kilt and fur-topped boots, same painted style, shown in full body, turned three-quarters toward the LEFT side of the picture, facing left."
GB="a skinny gangly young wannabe pirate with long blond hair tied in a ponytail, a goofy hopeful grin, a loose white shirt with puffy sleeves, a brown belt, dark blue trousers tucked into black boots"
LC="a hulking ghost pirate captain with a translucent glowing green-blue body trailing ghostly wisps, a huge bushy black beard, a large black tricorn captain's hat, a long dark captain's coat with gold buttons, glowing eyes and an evil grin"
DG="a tall anthropomorphic cartoon dog detective walking upright, short smooth brown fur, a long snout with a black nose, long floppy ears, a big cheerful toothy grin, a grey-blue suit with a white shirt and a wide tie with diagonal blue and black stripes, a matching grey-blue fedora hat, big bare brown dog feet without shoes"
RB="a small hyperactive cartoon rabbit-like creature with a smooth plain white body and no clothes, very long upright ears with pink insides, small round black dot eyes, a tiny pink nose, a huge wide grin full of small pointed teeth"
IN="a rugged adventurous archaeologist in his early forties with short brown hair and a few days of stubble, a battered brown fedora with a dark band, a worn dark brown leather jacket over a beige khaki shirt open at the collar with rolled sleeves, a canvas satchel strap across his chest, a coiled bullwhip at his hip"
typeset -A P R
P[c_guybrush]="Full body from the top of the head down to his boots, with empty magenta space above and below: $GB, one hand raised proudly as if announcing that he wants to be a pirate. $SP"
P[c_lechuck]="Full body from the top of the hat down to his boots, with empty magenta space above and below: $LC, one arm raised menacingly. $SP"
P[r_monkeyc]="$HL A moonlit tropical pirate harbour at night: a wooden dock, palm trees, a tavern with glowing windows, barrels of grog, and a glowing green ghost ship anchored in the bay. Three separate figures, from left to right: first $LC, looming on the left side of the dock; second the hero in the middle, facing left toward the ghost captain, holding up a frothy mug of root beer at him; third $GB, hiding behind the hero on the right, peeking out. Each wears only his own clothes. $ST"; R[r_monkeyc]=hero_left.png
P[r_indianac]="$HL Inside an ancient overgrown jungle temple lit by torches: a small golden idol on a carved stone pedestal in the middle, a pit full of snakes in the foreground, a huge round stone boulder at the top of a ramp behind. Two separate people, from left to right: first $IN, raising a warning hand toward the hero; second the hero on the right, facing left toward the archaeologist, carefully holding a big wheel of yellow cheese with both hands, ready to swap it with the idol. Each person wears only his own clothes. $ST"; R[r_indianac]=hero_left.png
P[r_sammaxc]="$HL A sunny desert roadside attraction along a dusty highway: a giant wheel of yellow cheese as big as a house on a wooden platform, a large blank weathered billboard, a vintage 1960s police sedan painted plain black and white with no lettering at all. Two separate figures, from left to right: first $DG, talking; second the hero on the right, facing left toward the dog and listening, with $RB perched on his shoulder. Each wears only his own clothes. There is no writing anywhere in the picture. $ST"; R[r_sammaxc]=hero_left.png
# Expressions du héros (demande de Stéphan, 24/11) : plus de sourire figé, une expression lisible par scène.
P[r_monkeyd]="$HL His usual smirk is gone: he frowns with brave determination, jaw clenched, eyebrows lowered, no smile at all. A moonlit tropical pirate harbour at night: a wooden dock, palm trees, a tavern with glowing windows, barrels of grog, and a glowing green ghost ship anchored in the bay. Three separate figures, from left to right: first $LC, looming on the left side of the dock; second the hero in the middle, facing left toward the ghost captain, holding up a frothy mug of root beer at him like a weapon; third $GB, hiding behind the hero on the right, peeking out, terrified. Each wears only his own clothes. $ST"; R[r_monkeyd]=hero_left.png
P[r_indianad]="$HL His usual smirk is gone: he looks nervous and tense, eyes wide, teeth clenched in a worried grimace, a drop of sweat on his brow, no smile at all. Inside an ancient overgrown jungle temple lit by torches: a small golden idol on a carved stone pedestal in the middle, a pit full of snakes in the foreground, a huge round stone boulder at the top of a ramp behind. Two separate people, from left to right: first $IN, raising a warning hand toward the hero; second the hero on the right, facing left toward the archaeologist, carefully holding a big wheel of yellow cheese with both hands, ready to swap it with the idol. Each person wears only his own clothes. $ST"; R[r_indianad]=hero_left.png
P[r_sammaxf]="$HL His usual smirk is gone: he looks puzzled and doubtful, one eyebrow raised, mouth twisted sideways, no smile at all. A sunny desert roadside attraction along a dusty highway: a giant wheel of yellow cheese as big as a house on a wooden platform, a large blank weathered billboard, a vintage 1960s police sedan painted plain black and white with no lettering at all. Two separate figures, from left to right: first $DG, talking with a big grin; second the hero on the right, facing left toward the dog and listening, with $RB perched on his shoulder. Each wears only his own clothes. There is no writing anywhere in the picture. $ST"; R[r_sammaxf]=hero_left.png
ids=("$@")
for id in $ids; do
  for s in 1 2; do
    if [[ $id == c_* ]]; then out="persos/${id}_$s.png"; sz=1024x1280; else out="${id}_$s.png"; sz=1280x720; fi
    [ -f "$out" ] && continue
    seed=$(( ${#id} * 1000 + s * 113 + 7171 ))
    refs=(); [ -n "${R[$id]}" ] && refs=(-i "${R[$id]}")
    flux-image "${P[$id]}" $refs -s $sz --seed $seed -o "$out" >/dev/null 2>&1
    echo "$(date +%H:%M:%S) ok $out"
  done
done
